mapper.select:
SELECT  FROM t_agreement_capability
WHERE agreement_id IN #{id}
ORDER BY agreement_capability_id

mapper.update:
UPDATE t_agreement_capability
SET effective_from = #{effectiveFrom}, effective_to = #{effectiveTo}, rolling_reserve_rate = #{rollingReserveRate},
    rolling_reserve_days = #{rollingReserveDays}, require_3ds = #{require3ds}, update_time = #{now}
WHERE agreement_capability_id = #{capability.agreementCapabilityId} AND update_time = #{capability.updateTime}
